import{I as m,_ as u,y as r,a4 as c,e as h,h as y,f as p,g}from"./index-x1UwFgwN.js";import{r as d,j as e}from"./react-B-hu5P_j.js";import{R as v}from"./FolderOpenOutlined-CklYUCgq.js";var b={icon:{tag:"svg",attrs:{viewBox:"64 64 896 896",focusable:"false"},children:[{tag:"path",attrs:{d:"M916 210H376c-17.7 0-32 14.3-32 32v236H108c-17.7 0-32 14.3-32 32v272c0 17.7 14.3 32 32 32h540c17.7 0 32-14.3 32-32V546h236c17.7 0 32-14.3 32-32V242c0-17.7-14.3-32-32-32zm-504 68h200v200H412V278zm-68 468H144V546h200v200zm268 0H412V546h200v200zm268-268H680V278h200v200z"}}]},name:"build",theme:"outlined"},x=function(t,i){return d.createElement(m,u({},t,{ref:i,icon:b}))},q=d.forwardRef(x);const f={ru:{"raqamli-manbalarni-tahlil-qilish":{title:"Метод анализа цифровых исторических источников",goal:"Формирование у будущих учителей истории навыков поиска, изучения, анализа и использования в процессе урока цифровых исторических документов, фотографий, карт, рукописей и архивных материалов.",exampleTopic:"Эпоха Амира Темура на основе исторических источников",example:"Преподаватель представляет студентам цифровые исторические источники, относящиеся к эпохе Амира Темура. Например:",exampleItems:["Электронная копия произведения «Уложения Темура»;","Исторические карты эпохи Амира Темура;","фотографии архитектурных памятников того времени."],steps:["Студенты ищут исторические источники на цифровых платформах.","Определяет автора, период создания и цель выбранного источника.","Анализирует значение источника в освещении исторических событий.","Сравнивает информацию из нескольких источников.","Подготавливает краткую презентацию на основе полученных результатов."],topicTitle:"Узбекская государственность в период правления Амира Темура"},"aqliy-hujum":{title:"Метод анализа исторических проблем на основе мозгового штурма",goal:"Развитие у студентов навыков самостоятельного мышления, подхода к проблеме с разных точек зрения, выявления причин исторических событий и обоснования своего мнения фактами.",exampleTopic:"Формирование независимых государств в Мавераннахре в IX веке",example:"Учитель в начале занятия задает следующий проблемный вопрос:",question:"Почему в IX веке в Мавераннахре произошел процесс усиления власти местных династий и формирования независимых государств?",steps:["Учитель задает проблемный вопрос.","Студенты свободно выражают свое мнение.","Высказанные мнения записываются на электронную доску или интерактивную платформу.","Студенты делят мнения на политические, экономические, социальные и культурные факторы.","Каждая группа проверяет свое мнение с помощью цифровых исторических источников.","На основе доказательств формируется общее заключение."],topicTitle:"Государства Мавераннахра и Хорасана в IX–XII веках"},"virtual-rekonstruksiya":{title:"Метод виртуальной исторической реконструкции",goal:"Развитие исторического мышления студентов путем переосмысления исторических событий, архитектурных памятников, городов и исторической среды с помощью цифровых технологий.",exampleTopic:"Древний Самарканд - город Афрасиаб",example:"Преподаватель продемонстрирует студентам археологические находки, настенные росписи, исторические карты и материалы 3D-реконструкции древнего городища Афросиаб.",steps:["Студенты изучают археологические и цифровые источники, относящиеся к Афрасиабу.","Определяет расположение и историческую структуру города.","Представляет вид города на основе исторических изображений и археологических данных.","Создает простую 3D-модель или цифровой макет.","Обосновывает созданную модель историческими источниками."]},"interaktiv-xaritalar":{title:"Метод работы с интерактивными историческими картами",goal:"Обучение географическим особенностям исторических событий, границ государств, военных походов, миграции и торговых путей с помощью цифровых карт.",exampleTopic:"Великий шелковый путь и его историческое значение",example:"Преподаватель вместе со студентами изучает основные направления Великого шелкового пути с помощью интерактивной карты.",steps:["Студенты открывают цифровую карту.","Определяет основные направления Великого шелкового пути.","Определяет расположение Самарканда, Бухары, Хивы, Термеза и других исторических центров.","Изучает экономические и культурные связи, осуществлявшиеся через торговые пути.","Готовит историческое заключение на основе карты."],topicTitle:"Великий шёлковый путь — путь диалога и сотрудничества"},"qiyosiy-tarixiy-tahlil":{title:"Метод сравнительно-исторического цифрового анализа",goal:"Развитие аналитического мышления студентов путем сравнения исторических периодов, государств, политических процессов и деятельности исторических личностей на основе цифровых источников.",exampleTopic:"Политико-экономическое развитие государства Саманидов и Караханидов",example:"Преподаватель предоставит студентам электронные исторические источники, карты, изображения монет и историческую информацию о двух странах.",steps:["Студенты изучают цифровые источники, связанные с государствами Саманидов и Караханидов.","Анализирует образование и политическое управление государств.","Сравнивает развитие экономической жизни, торговли, культуры и науки.","Размещает сходства и различия в электронной таблице.","Делает выводы на основе сравнительного анализа."],topicTitle:"Государства Мавераннахра и Хорасана в IX–XII веках"},"raqamli-tarixiy-tadqiqot":{title:"Метод цифрового исторического исследования",goal:"Формирование у студентов навыков самостоятельного исторического исследования, использования электронных библиотек, цифровых архивов, научных баз данных и исторических документов.",exampleTopic:"Джадидское движение и его представители",example:"Преподаватель поручает студентам самостоятельно изучить деятельность представителей джадидского движения через цифровые источники.",steps:["Студенты ищут литературу о джадидизме в электронных библиотеках.","Изучает цифровые копии исторических газет и журналов.","Собирает информацию о жизни и деятельности представителей джадидизма.","Сортирует данные по достоверности и исторической значимости.","Подготавливает электронный отчет об исследовании."]},"muammoli-vaziyatlarni-modellashtirish":{title:"Метод моделирования проблемных исторических ситуаций",goal:"Развитие у студентов способности выявлять исторические проблемы, анализировать различные точки зрения, принимать решения с учетом исторических условий и делать обоснованные выводы.",exampleTopic:"Политика централизации государства Амира Темура",example:"Преподаватель представляет студентам следующую проблемную ситуацию:",question:"Представьте, что вы являетесь советником, участвующим в политических процессах в Мавераннахре в XIV веке. В стране царит политическая раздробленность. Какие политические меры вы бы предложили для объединения государства и укрепления центральной власти?",steps:["Студенты изучают политическую ситуацию в Мавераннахре в XIV веке.","Анализирует исторические карты, письменные источники и электронные материалы.","Определяет причины возникновения проблемы.","Разрабатывает альтернативные решения в малых группах.","Обосновывает свои предложения историческими фактами.","Сравнивает с реальными политическими решениями времен Амира Темура."],topicTitle:"Узбекская государственность в период правления Амира Темура"},gamifikatsiya:{title:"Метод преподавания истории на основе геймификации",goal:"Повышение интереса студентов к истории путем внедрения в учебный процесс игровых элементов, баллов, рейтинга, заданий, конкурсов и интерактивных вопросов.",exampleTopic:"Исторические личности в истории Узбекистана",example:"Учитель организует викторину о деятельности исторических личностей, используя Kahoot, Quizizz или другие интерактивные платформы.",steps:["Учитель подготавливает 15-20 вопросов об исторических личностях.","Студенты подключаются к викторине по телефону или компьютеру.","Отвечает на вопросы в установленное время.","За правильные ответы начисляются баллы.","В заключение анализируются результаты и объясняются неправильные ответы."]},"raqamli-loyiha":{title:"Метод преподавания истории на основе цифрового проекта",goal:"Развитие исследовательских, проектных и методических организаторских компетенций студентов путем направления их на разработку самостоятельного или коллективного цифрового проекта по определенной исторической теме.",exampleTopic:"Великие ученые и их вклад в мировую цивилизацию",example:"Преподаватель делит студентов на группы. Каждая группа подготовит цифровой проект об одном из великих ученых Центральной Азии.",steps:["Студенты выбирают тему проекта.","Собирает информацию из электронной библиотеки и научных источников.","Изучает жизнь, научную деятельность и наследие исторической личности.","Создает цифровую презентацию, веб-страницу, электронную карту или видеопроект.","Защищает результаты проекта.","Преподаватель оценивает результаты проекта на основе установленных критериев."],topicTitle:"Эпоха Возрождения IX–XII веков. Вклад наших предков в мировую цивилизацию"}},en:{"raqamli-manbalarni-tahlil-qilish":{title:"Method for analyzing digital historical sources",goal:"To develop skills in future history teachers to search, study, analyze, and utilize digital historical documents, photographs, maps, manuscripts, and archival materials during the lesson process.",exampleTopic:"The Era of Amir Temur Based on Historical Sources",example:"The teacher presents digital historical sources related to the era of Amir Temur to the students. For example:",exampleItems:["Electronic copy of the “Temur Tuzuklari” work;","Historical maps of the era of Amir Temur;","photographs of architectural monuments of that time."],steps:["Students search for historical sources on digital platforms.","Identifies the author, creation period, and purpose of the selected source.","Analyzes the significance of the source in covering historical events.","Compares information from several sources.","Prepares a brief presentation based on the results obtained."],topicTitle:"Uzbek statehood under Amir Temur"},"aqliy-hujum":{title:"The method of analyzing historical problems based on brainstorming",goal:"To develop students' skills in independent thinking, approaching the problem from different perspectives, identifying the causes of historical events, and substantiating their opinion with facts.",exampleTopic:"Formation of independent states in Maveraunnahr in the 9th century",example:"The teacher asks the following problem-based question at the beginning of the lesson:",question:"Why did the process of strengthening the power of local dynasties and forming independent states occur in Mawarannahr in the 9th century?",steps:["The teacher asks a problem question.","Students express their opinions freely.","The expressed opinions are recorded on an electronic board or an interactive platform.","Students divide opinions into political, economic, social, and cultural factors.","Each group verifies their opinion using digital historical sources.","A general conclusion is formed based on the evidence."],topicTitle:"The states of Transoxiana and Khorasan in the 9th–12th centuries"},"virtual-rekonstruksiya":{title:"Virtual historical reconstruction method",goal:"To develop students' historical thinking by reinterpreting historical events, architectural monuments, cities, and the historical environment using digital technologies.",exampleTopic:"Ancient Samarkand - the city of Afrasiab",example:"The instructor will demonstrate archaeological finds, wall paintings, historical maps, and 3D reconstruction materials of the ancient Afrasiab settlement to the students.",steps:["Students study archaeological and digital sources related to Afrasiab.","Determines the location and historical structure of the city.","Presents the city's appearance based on historical images and archaeological data.","Creates a simple 3D model or digital layout.","Justifies the created model using historical sources."]},"interaktiv-xaritalar":{title:"Method for working with interactive historical maps",goal:"Teaching the geographical features of historical events, state borders, military campaigns, migration, and trade routes using digital maps.",exampleTopic:"The Great Silk Road and Its Historical Significance",example:"The teacher, together with the students, studies the main directions of the Great Silk Road using an interactive map.",steps:["Students open a digital card.","Identifies the main directions of the Great Silk Road.","Determines the location of Samarkand, Bukhara, Khiva, Termez, and other historical centers.","Examines economic and cultural ties carried out through trade routes.","Prepares a historical conclusion based on the map."],topicTitle:"The Great Silk Road — a road of dialogue and cooperation"},"qiyosiy-tarixiy-tahlil":{title:"Comparative-historical numerical analysis method",goal:"Developing students' analytical thinking by comparing historical periods, states, political processes, and the activities of historical figures based on digital sources.",exampleTopic:"Political and Economic Development of the Samanid and Karakhanid States",example:"The instructor will provide students with electronic historical sources, maps, coin images, and historical information about the two countries.",steps:["Students study digital sources related to the Samanid and Karakhanid states.","Analyzes the formation and political governance of states.","Compares the development of economic life, trade, culture, and science.","Places similarities and differences in an electronic table.","Makes conclusions based on comparative analysis."],topicTitle:"The states of Transoxiana and Khorasan in the 9th–12th centuries"},"raqamli-tarixiy-tadqiqot":{title:"The digital historical research method",goal:"To develop students' skills in independent historical research, using electronic libraries, digital archives, scientific databases, and historical documents.",exampleTopic:"The Jadid Movement and Its Representatives",example:"The teacher instructs the students to independently study the activities of representatives of the Jadid movement through digital sources.",steps:["Students search for literature on Jadidism in electronic libraries.","Examines digital copies of historical newspapers and magazines.","Collects information about the lives and activities of representatives of Jadidism.","Sort data by reliability and historical significance.","Prepares an electronic study report."]},"muammoli-vaziyatlarni-modellashtirish":{title:"The method of modeling problematic historical situations",goal:"To develop students' ability to identify historical problems, analyze various points of view, make decisions considering historical conditions, and draw well-founded conclusions.",exampleTopic:"The Policy of Centralization of Amir Temur's State",example:"The teacher presents the following problem situation to the students:",question:"Imagine that you are an advisor participating in the political processes in Movarounnahr in the 14th century. Political fragmentation reigns in the country. What political measures would you propose for the unification of the state and the strengthening of central power?",steps:["Students study the political situation in Maveraunnahr in the 14th century.","Analyzes historical maps, written sources, and electronic materials.","Identifies the causes of the problem.","Develops alternative solutions in small groups.","Justifies his proposals with historical facts.","Compares with real political decisions from the time of Amir Temur."],topicTitle:"Uzbek statehood under Amir Temur"},gamifikatsiya:{title:"The method of teaching history based on gamification",goal:"To increase students' interest in history by introducing game elements, points, rating, tasks, competitions, and interactive questions into the educational process.",exampleTopic:"Historical Personalities in the History of Uzbekistan",example:"The teacher organizes a quiz about the activities of historical figures using Kahoot, Quizizz, or other interactive platforms.",steps:["The teacher prepares 15-20 questions about historical figures.","Students join the quiz via phone or computer.","Answers questions at the appointed time.","Points are awarded for correct answers.","In conclusion, the results are analyzed and the incorrect answers are explained."]},"raqamli-loyiha":{title:"History teaching method based on a digital project",goal:"To develop students' research, project, and methodological organizational competencies by directing them to develop an independent or collective digital project on a specific historical topic.",exampleTopic:"Great scientists and their contribution to world civilization",example:"The teacher divides the students into groups. Each group will prepare a digital project about one of the great scholars of Central Asia.",steps:["Students select a project topic.","Collects information from the electronic library and scientific sources.","Examines the life, scientific activities, and heritage of a historical figure.","Creates a digital presentation, web page, electronic map, or video project.","Defends project results.","The teacher evaluates the project results based on established criteria."],topicTitle:"The Renaissance of the 9th–12th centuries. Our ancestors’ contribution to world civilisation"}}},o={manba:{tone:"bg-blue-50 text-blue-700",bar:"bg-blue-500"},muammo:{tone:"bg-amber-50 text-amber-700",bar:"bg-amber-500"},vizual:{tone:"bg-emerald-50 text-emerald-700",bar:"bg-emerald-500"},interaktiv:{tone:"bg-violet-50 text-violet-700",bar:"bg-violet-500"}},I=Object.fromEntries(Object.keys(o).map(a=>[a,{...o[a],get label(){return r.t(`methodology.cat.${a}`)}}])),k=[{slug:"raqamli-manbalarni-tahlil-qilish",n:1,title:"Raqamli tarixiy manbalarni tahlil qiliş metodi",category:"manba",goal:"Bölajak tarix öqituvçilarida raqamli tarixiy hujjatlar, fotosuratlar, xaritalar, qölyozmalar va arxiv materiallarini izlaş, örganiş, tahlil qiliş hamda ulardan dars jarayonida foydalaniş könikmalarini şakllantiriş.",exampleTopic:"Amir Temur davri tarixiy manbalar asosida",example:"Öqituvçi talabalarga Amir Temur davriga oid raqamli tarixiy manbalarni taqdim etadi. Masalan:",exampleItems:["«Temur tuzuklari» asarining elektron nusxasi;","Amir Temur davriga oid tarixiy xaritalar;","öşa davr me’moriy obidalari fotosuratlari."],steps:["Talabalar raqamli platformalardan tarixiy manbalarni izlaydi.","Tanlangan manbaning muallifi, yaratilgan davri va maqsadini aniqlaydi.","Manbaning tarixiy voqealarni yoritişdagi ahamiyatini tahlil qiladi.","Bir neçta manbadagi ma’lumotlarni özaro taqqoslaydi.","Olingan natijalar asosida qisqa taqdimot tayyorlaydi."],topic:{slug:"amir-temur-davlati",title:"Amir Temur hukmronligi davrida özbek davlatçiligi"},tools:["sources","museum"]},{slug:"aqliy-hujum",n:2,title:"Aqliy hujum asosida tarixiy muammolarni tahlil qiliş metodi",category:"muammo",goal:"Talabalarning mustaqil fikrlaş, muammoga turli nuqtayi nazardan yondashish, tarixiy voqealar sabablarini aniqlaş va öz fikrini dalillar bilan asoslash könikmalarini rivojlantiriş.",exampleTopic:"IX asrda Movarounnahrda mustaqil davlatlarning şakllanişi",example:"Öqituvçi maşğulot boşida quyidagi muammoli savolni beradi:",question:"Nima sababdan IX asrda Movarounnahrda mahalliy sulolalar hokimiyatining kuçayişi va mustaqil davlatlarning şakllanişi jarayoni yuz berdi?",steps:["Öqituvçi muammoli savolni taqdim etadi.","Talabalar öz fikrlarini erkin bildiradi.","Bildirilgan fikrlar elektron doska yoki interaktiv platformaga yozib boriladi.","Talabalar fikrlarni siyosiy, iqtisodiy, ijtimoiy va madaniy omillarga ajratadi.","Har bir guruh öz fikrini raqamli tarixiy manbalar bilan tekşiradi.","Dalillar asosida umumiy xulosa şakllantiriladi."],topic:{slug:"ix-xii-asrlar-tarixi",title:"IX–XII asrlarda Movarounnahr va Xuroson davlatlari"},tools:["sources","lessons"]},{slug:"virtual-rekonstruksiya",n:3,title:"Virtual tarixiy rekonstruksiya metodi",category:"vizual",goal:"Tarixiy voqealar, me’moriy obidalar, şaharlar va tarixiy muhitni raqamli texnologiyalar yordamida qayta tasavvur qiliş orqali talabalarning tarixiy tafakkurini rivojlantiriş.",exampleTopic:"Qadimgi Samarqand — Afrosiyob şahri",example:"Öqituvçi talabalarga Afrosiyob qadimiy shaharchasining arxeologik topilmalari, devoriy suratlari, tarixiy xaritalari va 3D rekonstruksiya materiallarini namoyiş etadi.",steps:["Talabalar Afrosiyobga oid arxeologik va raqamli manbalarni örganadi.","Şaharning joylaşuvi va tarixiy tuzilişini aniqlaydi.","Tarixiy tasvirlar va arxeologik ma’lumotlar asosida şahar körinişini tasavvur qiladi.","Oddiy 3D model yoki raqamli maket yaratadi.","Yaratilgan modelni tarixiy manbalar bilan asoslaydi."],tools:["museum","explore"]},{slug:"interaktiv-xaritalar",n:4,title:"Interaktiv tarixiy xaritalar bilan işlaş metodi",category:"vizual",goal:"Tarixiy voqealar, davlatlar çegaralari, harbiy yurişlar, migratsiya va savdo yöllarining geografik xususiyatlarini raqamli xaritalar yordamida örgatiş.",exampleTopic:"Buyuk ipak yöli va uning tarixiy ahamiyati",example:"Öqituvçi talabalar bilan interaktiv xarita orqali Buyuk ipak yölining asosiy yönalişlarini örganadi.",steps:["Talabalar raqamli xaritani oçadi.","Buyuk ipak yölining asosiy yönalişlarini belgilaydi.","Samarqand, Buxoro, Xiva, Termiz va boşqa tarixiy markazlarning joylaşuvini aniqlaydi.","Savdo yöllari orqali amalga oşirilgan iqtisodiy va madaniy aloqalarni örganadi.","Xarita asosida tarixiy xulosa tayyorlaydi."],topic:{slug:"buyuk-ipak-yoli",title:"Buyuk ipak yöli — muloqot va hamkorlik yöli"},tools:["explore","sources"]},{slug:"qiyosiy-tarixiy-tahlil",n:5,title:"Qiyosiy-tarixiy raqamli tahlil metodi",category:"manba",goal:"Tarixiy davrlar, davlatlar, siyosiy jarayonlar va tarixiy şaxslar faoliyatini raqamli manbalar asosida qiyoslash orqali talabalarning tahliliy fikrlaş qobiliyatini rivojlantiriş.",exampleTopic:"Somoniylar va Qoraxoniylar davlatining siyosiy-iqtisodiy taraqqiyoti",example:"Öqituvçi talabalarga ikki davlatga oid elektron tarixiy manbalar, xaritalar, tangalar tasvirlari va tarixiy ma’lumotlarni taqdim etadi.",steps:["Talabalar Somoniylar va Qoraxoniylar davlatiga oid raqamli manbalarni örganadi.","Davlatlarning taşkil topişi va siyosiy boşqaruvini tahlil qiladi.","Iqtisodiy hayot, savdo, madaniyat va ilm-fan rivojini taqqoslaydi.","Öxshash va farqli jihatlarni elektron jadvalga joylaştiradi.","Qiyosiy tahlil asosida xulosa çiqaradi."],topic:{slug:"ix-xii-asrlar-tarixi",title:"IX–XII asrlarda Movarounnahr va Xuroson davlatlari"},tools:["sources","explore"]},{slug:"raqamli-tarixiy-tadqiqot",n:6,title:"Raqamli tarixiy tadqiqot metodi",category:"manba",goal:"Talabalarda mustaqil tarixiy izlaniş olib boriş, elektron kutubxonalar, raqamli arxivlar, ilmiy ma’lumotlar bazalari va tarixiy hujjatlardan foydalaniş könikmalarini şakllantiriş.",exampleTopic:"Jadidçilik harakati va uning namoyandalari",example:"Öqituvçi talabalarga jadidçilik harakati vakillarining faoliyatini raqamli manbalar orqali mustaqil örganişni topşiradi.",steps:["Talabalar elektron kutubxonalardan jadidçilikka oid adabiyotlarni izlaydi.","Tarixiy gazeta va jurnallarning raqamli nusxalarini örganadi.","Jadid namoyandalarining hayoti va faoliyati haqida ma’lumot töplaydi.","Ma’lumotlarni işonçliligi va tarixiy ahamiyati böyiça saralaydi.","Elektron tadqiqot hisoboti tayyorlaydi."],tools:["sources","profile"]},{slug:"muammoli-vaziyatlarni-modellashtirish",n:7,title:"Muammoli tarixiy vaziyatlarni modellaştiriş metodi",category:"muammo",goal:"Talabalarning tarixiy muammolarni aniqlaş, turli nuqtayi nazarlarni tahlil qiliş, tarixiy şaroitni hisobga olgan holda qaror qabul qiliş va dalillangan xulosa çiqariş qobiliyatini rivojlantiriş.",exampleTopic:"Amir Temurning davlatni markazlaştiriş siyosati",example:"Öqituvçi talabalarga quyidagi muammoli vaziyatni taqdim etadi:",question:"Tasavvur qiling, siz XIV asrda Movarounnahrdagi siyosiy jarayonlarda iştirok etayotgan maslahatçisiz. Mamlakatda siyosiy tarqoqlik mavjud. Davlatni birlaştiriş va markaziy hokimiyatni mustahkamlaş uçun qanday siyosiy çoralarni taklif qilgan bölardingiz?",steps:["Talabalar XIV asrdagi Movarounnahrning siyosiy vaziyatini örganadi.","Tarixiy xaritalar, yozma manbalar va elektron materiallarni tahlil qiladi.","Muammoning kelib çiqiş sabablarini aniqlaydi.","Kiçik guruhlarda muqobil yeçimlarni işlab çiqadi.","Takliflarini tarixiy dalillar bilan asoslaydi.","Amir Temur davridagi real siyosiy qarorlar bilan qiyoslaydi."],topic:{slug:"amir-temur-davlati",title:"Amir Temur hukmronligi davrida özbek davlatçiligi"},tools:["sources","lessons"]},{slug:"gamifikatsiya",n:8,title:"Gamifikatsiya asosida tarixni öqitiş metodi",category:"interaktiv",goal:"Öquv jarayoniga öyin elementlari, ball, reyting, topşiriq, musobaqa va interaktiv savollarni joriy etiş orqali talabalarning tarix faniga qiziqişini oşiriş.",exampleTopic:"Özbekiston tarixidagi tarixiy şaxslar",example:"Öqituvçi Kahoot, Quizizz yoki boşqa interaktiv platformalardan foydalanib, tarixiy şaxslar faoliyatiga oid viktorina taşkil qiladi.",steps:["Öqituvçi tarixiy şaxslar haqida 15–20 ta savol tayyorlaydi.","Talabalar telefon yoki kompyuter orqali viktorinaga ulanadi.","Savollarga belgilangan vaqt içida javob beradi.","Tög’ri javoblar uçun ball beriladi.","Yakunda natijalar tahlil qilinadi va notög’ri javoblar izohlanadi."],tools:["assignments"]},{slug:"raqamli-loyiha",n:9,title:"Raqamli loyiha asosida tarixni öqitiş metodi",category:"interaktiv",goal:"Talabalarni muayyan tarixiy mavzu böyiça mustaqil yoki jamoaviy raqamli loyiha işlab çiqişga yönaltiriş orqali ularning tadqiqotçilik, loyihalaş va metodik taşkilotçilik kompetensiyalarini rivojlantiriş.",exampleTopic:"Buyuk allomalar va ularning jahon sivilizatsiyasiga qöşgan hissasi",example:"Öqituvçi talabalarni guruhlarga ajratadi. Har bir guruh Markaziy Osiyoda yetişib çiqqan buyuk allomalardan biri haqida raqamli loyiha tayyorlaydi.",steps:["Talabalar loyiha mavzusini tanlaydi.","Elektron kutubxona va ilmiy manbalardan ma’lumot töplaydi.","Tarixiy şaxsning hayoti, ilmiy faoliyati va merosini örganadi.","Raqamli taqdimot, veb-sahifa, elektron xarita yoki videoloyiha yaratadi.","Loyiha natijalarini himoya qiladi.","Öqituvçi loyiha natijalarini belgilangan mezonlar asosida baholaydi."],topic:{slug:"sharq-uygonish-davri",title:"IX–XII asrlarda Uyğoniş davri. Ajdodlarimizning jahon sivilizatsiyasiga qöşgan hissasi"},tools:["sources","profile"]}],n=(a,t)=>{var l;const i=c();return i==="uz"||(l=f[i][a])==null?void 0:l[t]},S=k.map(a=>{const t={...a};for(const i of["title","goal","exampleTopic","example","exampleItems","question","steps"])a[i]!==void 0&&Object.defineProperty(t,i,{enumerable:!0,get:()=>n(a.slug,i)??a[i]});if(a.topic){const i=a.topic;Object.defineProperty(t,"topic",{enumerable:!0,get:()=>({slug:i.slug,title:n(a.slug,"topicTitle")??i.title})})}return t}),s={sources:{icon:e.jsx(g,{}),to:"/app/sources"},museum:{icon:e.jsx(p,{}),to:"/app/museum"},explore:{icon:e.jsx(y,{}),to:"/app/explore"},lessons:{icon:e.jsx(q,{}),to:"/app/lessons"},assignments:{icon:e.jsx(h,{}),to:"/app/assignments"},profile:{icon:e.jsx(v,{}),to:"/app/profile"}},w=Object.fromEntries(Object.keys(s).map(a=>[a,{...s[a],get label(){return r.t(`methodology.tool.${a}`)},get desc(){return r.t(`methodology.tool.${a}Desc`)}}]));export{I as C,S as M,w as T};
